def exp_mod(a, b):
    result = 1
    while b > 0:
        if b % 2 == 1:
            result = (result * a) % MOD
        a = (a * a) % MOD
        b //= 2
    return result

def inv_mod(a):
    return exp_mod(a, MOD - 2)

def solve():
    n = int(stdin.readline())
    A = list(map(int, stdin.readline().split()))

    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        new_dp = [0] * (i + 1)
        total_prob = 0

        for j in range(i):
            prob = dp[j] * inv_mod(j + 1)
            total_prob = (total_prob + prob) % MOD

            for k in range(j + 1):
                new_dp[k] = (new_dp[k] + dp[j] * exp_mod(A[i - 1], k)) % MOD

        dp = new_dp

    expected_value = 0
    for i in range(n):
        expected_value = (expected_value + dp[i]) % MOD

    stdout.write(str(expected_value) + '\n')

if __name__ == "__main__":
    solve()
